/** Símbolo de la marca: uña estilizada con destello. */
function brand_mark(int $size = 34): string
{
    return '<svg class="brand-mark" width="' . $size . '" height="' . $size . '" viewBox="0 0 48 48" aria-hidden="true" focusable="false">'
        . '<circle cx="24" cy="24" r="23" fill="var(--c-blush-100, #F8E8ED)"/>'
        . '<path d="M24 9c-6.2 0-9.5 5.6-9.5 12.2V33a5 5 0 0 0 5 5h9a5 5 0 0 0 5-5V21.2C33.5 14.6 30.2 9 24 9Z" fill="var(--c-fuchsia, #C74375)"/>'
        . '<path d="M24 12.5c-4 0-6.3 3.8-6.3 8.6V23h12.6v-1.9c0-4.8-2.3-8.6-6.3-8.6Z" fill="#fff" opacity=".28"/>'
        . '<path d="M36.5 8.5l1 2.6 2.6 1-2.6 1-1 2.6-1-2.6-2.6-1 2.6-1z" fill="var(--c-wine, #6F2445)"/>'
